contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Ensure version is in a reasonable range (>= 1 for a valid version)
        vm.assume(version >= 1 && version <= 1e6);

        // We need to simulate some state so that atVersion returns a version with a non-zero price.
        // Since we can't set oracle prices directly, we use a simpler approach:
        // The bug is that oracle() returns address(0) instead of the real oracle.
        // We call atVersion(0) which should revert because oracle is not a contract.
        // We then call atVersion(version > 0) which should also revert.
        // So the property is: calling atVersion with any version should revert when oracle is broken.

        bool reverted = false;
        try c.atVersion(version) returns (IOracleProvider.OracleVersion memory ov) {
            // If it doesn't revert, the price should be non-negative (not necessarily non-zero)
            // But with a fake oracle, the price would be 0 from the mock return.
            // Actually, since address(0) as oracle, the call to oracle().atVersion will revert.
            // So we should not reach here.
        } catch {
            reverted = true;
        }

        // The property: atVersion always reverts when oracle is address(0)
        assertTrue(reverted, "atVersion should revert when oracle is address(0)");
    }
}

