import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // Ensure version is within reasonable bounds to avoid revert on out-of-range
        vm.assume(version <= type(uint128).max);

