pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // For a freshly deployed contract, atVersion(0) should equal currentVersion()
        // because the initial oracle version is 0
        (bool successA, bytes memory retA) = address(c).call(abi.encodeWithSignature("atVersion(uint256)", 0));
        (bool successB, bytes memory retB) = address(c).call(abi.encodeWithSignature("currentVersion()"));
        assertTrue(successA && successB);
        // The oracle version structure: (uint256 version, uint256 timestamp, int256 price)
        (uint256 vA, uint256 tA, int256 pA) = abi.decode(retA, (uint256, uint256, int256));
        (uint256 vB, uint256 tB, int256 pB) = abi.decode(retB, (uint256, uint256, int256));
        // After deployment with no oracle sync, both should return the same initial version
        assertTrue(vA == vB, "Version mismatch");
        assertTrue(tA == tB, "Timestamp mismatch");
        assertTrue(pA == pB, "Price mismatch");
    }
}

