pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Bound oracleVersion to a reasonable range to avoid excessive gas
        oracleVersion = bound(oracleVersion, 0, 100);

        // Get the transformed price from atVersion
        IOracleProvider.OracleVersion memory versionFromAt;
        bool atSucceeded;
        try c.atVersion(oracleVersion) returns (IOracleProvider.OracleVersion memory ov) {
            versionFromAt = ov;
            atSucceeded = true;
        } catch {
            atSucceeded = false;
        }

        // Get the raw oracle price from currentVersion
        IOracleProvider.OracleVersion memory currentVersion;
        bool currentSucceeded;
        try c.oracle().currentVersion() returns (IOracleProvider.OracleVersion memory ov) {
            currentVersion = ov;
            currentSucceeded = true;
        } catch {
            currentSucceeded = false;
        }

        // Both calls must succeed or both fail (e.g., if no oracle set)
        if (atSucceeded != currentSucceeded) {
            assertTrue(false, "Consistency failure: one call succeeded and the other failed");
        }

        if (atSucceeded) {
            // Compute the expected transformed price
            Fixed18 transformedPrice = c.payoffDefinition().transform(currentVersion.price);
            // The rule: atVersion returns the same version and price as currentVersion, with price transformed
            assertTrue(
                versionFromAt.version == currentVersion.version &&
                versionFromAt.timestamp == currentVersion.timestamp &&
                versionFromAt.price == transformedPrice,
                "atVersion must return currentVersion transformed by payoffDefinition"
            );
        }
    }
}

